public XMLBuilder addElement(final String name, final Map<String, String> attributes, final String text) {
        startElement(name, attributes);
        if (StringUtils.isNotEmpty(text)) {
            builder.append(text);
            emptyElementInProgress = false;
        }

        return endElement();
    }
